import{_ as t,o as a,c as i,a2 as e}from"./chunks/framework.p9eYlHBT.js";const k=JSON.parse('{"title":"实验沙箱（Sandbox）","description":"","frontmatter":{},"headers":[],"relativePath":"SANDBOX.md","filePath":"SANDBOX.md","lastUpdated":1794410944000}'),d={name:"SANDBOX.md"};function o(n,s,l,p,h,c){return a(),i("div",null,[...s[0]||(s[0]=[e(`<h1 id="实验沙箱-sandbox" tabindex="-1">实验沙箱（Sandbox） <a class="header-anchor" href="#实验沙箱-sandbox" aria-label="Permalink to &quot;实验沙箱（Sandbox）&quot;">​</a></h1><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>Agent 执行「实验性操作」——新建/删除临时文件、执行临时代码——如果直接落在 宿主工作目录与宿主环境里，可能误删文件、写坏环境。本模块为这类操作提供<strong>隔离 执行环境</strong>：文件操作全部重定向到独立沙箱根目录，命令在脱敏环境中运行，宿主 文件与凭据不受影响。</p><h2 id="使用方式-agent-工具" tabindex="-1">使用方式（Agent 工具） <a class="header-anchor" href="#使用方式-agent-工具" aria-label="Permalink to &quot;使用方式（Agent 工具）&quot;">​</a></h2><p>内置工具 <code>sandbox</code>（与 <code>bash</code>、<code>file-write</code> 等同级注册），动作如下：</p><table tabindex="0"><thead><tr><th>动作</th><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>run</code></td><td><code>command</code>（必填）、<code>timeout?</code></td><td>在沙箱内执行 shell 命令（cmd/sh），输出/退出码/stderr 返回</td></tr><tr><td><code>write</code></td><td><code>path</code>、<code>content</code></td><td>在沙箱内写文件（自动建父目录）</td></tr><tr><td><code>read</code></td><td><code>path</code></td><td>读沙箱内文件</td></tr><tr><td><code>delete</code></td><td><code>path</code></td><td>删除沙箱内文件/目录（递归）</td></tr><tr><td><code>list</code></td><td><code>path?</code></td><td>列出沙箱内内容（递归）</td></tr><tr><td><code>copy-in</code></td><td><code>source</code>（宿主路径）、<code>dest?</code></td><td>把宿主文件/目录（只读）导入沙箱</td></tr><tr><td><code>copy-out</code></td><td><code>path</code>、<code>dest</code>（宿主路径）</td><td>把沙箱产物导出到宿主 —— <strong>唯一出口，需权限审批</strong></td></tr><tr><td><code>status</code></td><td>—</td><td>查看当前会话沙箱根路径</td></tr></tbody></table><p>示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sandbox run     command=&quot;node -e \\&quot;console.log(&#39;tmp ok&#39;)\\&quot;&quot;</span></span>
<span class="line"><span>sandbox write   path=&quot;exp/test.js&quot; content=&quot;console.log(1+1)&quot;</span></span>
<span class="line"><span>sandbox run     command=&quot;node exp/test.js &gt; result.txt&quot;</span></span>
<span class="line"><span>sandbox read    path=&quot;result.txt&quot;</span></span>
<span class="line"><span>sandbox delete  path=&quot;exp&quot;</span></span>
<span class="line"><span>sandbox copy-out path=&quot;result.txt&quot; dest=&quot;./tmp-result.txt&quot;</span></span></code></pre></div><p>沙箱按<strong>会话（sessionId）隔离</strong>：同一会话复用同一沙箱根，会话间互不可见。</p><h2 id="安全模型" tabindex="-1">安全模型 <a class="header-anchor" href="#安全模型" aria-label="Permalink to &quot;安全模型&quot;">​</a></h2><ol><li><strong>路径围栏</strong>：<code>resolvePath</code> 归一化后必须落在沙箱根内，<code>..</code> 逃逸或沙箱外的 绝对路径抛 <code>SandboxEscapeError</code>（工具层返回错误结果）。</li><li><strong>环境脱敏</strong>：子进程环境剔除 <code>*API_KEY</code> / <code>*TOKEN</code> / <code>*SECRET</code> / <code>*PASSWORD</code> 等敏感变量及 <code>FENG_*</code>、<code>MULTICA_*</code> 前缀；<code>HOME</code> / <code>USERPROFILE</code> / <code>TEMP</code> / <code>TMP</code> 指向沙箱内目录；注入 <code>FENG_SANDBOX=1</code> 标记（临时代码可自检）。</li><li><strong>超时强杀</strong>：命令默认 120s 超时；Windows 用 <code>taskkill /T /F</code> 杀进程树， POSIX 用进程组 <code>SIGKILL</code>，防止失控进程残留。</li><li><strong>显式数据流通</strong>：宿主 → 沙箱只能走 <code>copy-in</code>（源只读）；沙箱 → 宿主只能走 <code>copy-out</code>（工具层权限审批，默认询问用户）。</li><li><strong>自动清理</strong>：<code>dispose()</code> 递归删除沙箱根（幂等，对瞬时文件锁有限重试）。</li></ol><h2 id="编程接口-typescript" tabindex="-1">编程接口（TypeScript） <a class="header-anchor" href="#编程接口-typescript" aria-label="Permalink to &quot;编程接口（TypeScript）&quot;">​</a></h2><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { Sandbox } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;@fengagent/tools&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> sb</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Sandbox</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 根目录在 os.tmpdir() 下</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sb.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">writeFile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;exp/a.txt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sb.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">runCommand</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;node exp/a.js&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// { exitCode, stdout, stderr, timedOut }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sb.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">copyOut</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;exp/a.txt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/host/dest/a.txt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sb.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dispose</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><h2 id="设计取舍与已知边界" tabindex="-1">设计取舍与已知边界 <a class="header-anchor" href="#设计取舍与已知边界" aria-label="Permalink to &quot;设计取舍与已知边界&quot;">​</a></h2><ul><li><strong>软隔离</strong>：这是「路径围栏 + 环境脱敏」的进程级隔离，不是 OS 级沙箱 （Docker/bwrap）。刻意 <code>cd</code> 出沙箱根的命令仍能访问宿主 —— 用于防误操作、 防凭据泄露，不防恶意逃逸。</li><li><strong>输出捕获</strong>：命令以 <code>( ... )</code> 子组包裹后重定向到沙箱内文件（非管道）， 兼容受限环境并避免大输出死锁；命令内含未配对括号时需自行转义。</li><li><strong>copy-out 是唯一出口</strong>：与既有 <code>file-write</code> 权限语义一致，需要用户确认。</li><li>沙箱内的写操作<strong>不触发</strong>权限询问（隔离内安全），与既有 <code>bash</code>/<code>file-write</code> 的审批行为相互独立，互不影响。</li></ul>`,15)])])}const g=t(d,[["render",o]]);export{k as __pageData,g as default};
